import { createHash } from 'node:crypto';
export const commit='a'.repeat(40),tree='b'.repeat(40);
export const sourceText='---\r\nname: careful-review\r\ndescription: Review carefully\r\nlicense: MIT\r\n---\r\nRead [reference](references/index.md).\r\n';
export const referenceText='---\ntype: Agent\nverified: true\n---\nUntrusted text café\n```\n';
export function scriptedGitHub(files:Record<string,string|{mode:string;content:string}>={'odd-folder/SKILL.md':sourceText,'odd-folder/references/index.md':referenceText,'odd-folder/scripts/check.sh':'#!/bin/sh\nprintf never-execute'},version:{commit?:string;tree?:string}={}){
 const calls:string[]=[];const rootTree=version.tree??tree,commitId=version.commit??commit;const treePaths=new Map<string,string>([[rootTree,'']]);const blobs=new Map<string,string>();const entries=Object.entries(files).map(([path,value])=>{const content=typeof value==='string'?value:value.content;const sha=createHash('sha1').update(`blob ${Buffer.byteLength(content)}\0`).update(content).digest('hex');blobs.set(sha,content);return {path,mode:typeof value==='string'?'100644':value.mode,type:typeof value!=='string'&&value.mode==='160000'?'commit':'blob',sha,size:Buffer.byteLength(content)};});
 return {calls,entries,async get(path:string,_signal:AbortSignal):Promise<unknown>{calls.push(path);if(path==='/repos/example/tools')return {private:false,default_branch:'main',full_name:'example/tools'};if(path.startsWith('/repos/example/tools/commits/'))return {sha:commitId,commit:{tree:{sha:rootTree}}};if(path.includes('/git/trees/')){const sha=path.split('/').at(-1)!.split('?')[0]!,root=treePaths.get(sha);if(root===undefined)throw Error('Unknown scripted tree');const selected=entries.filter(e=>e.path.startsWith(root)).map(e=>({...e,path:e.path.slice(root.length)}));if(path.endsWith('?recursive=1'))return {sha,truncated:false,tree:selected};const direct=new Map<string,unknown>();for(const e of selected){if(e.path.includes('/')){const folder=e.path.split('/')[0]!,id=createHash('sha1').update('tree:'+root+folder).digest('hex');treePaths.set(id,root+folder+'/');direct.set(folder,{path:folder,mode:'040000',type:'tree',sha:id});}else direct.set(e.path,e);}return {sha,truncated:false,tree:[...direct.values()]};}if(path.startsWith('/repos/example/tools/git/blobs/')){const sha=path.split('/').at(-1)!,text=blobs.get(sha);if(text===undefined)throw Error('Unknown scripted blob');return {sha,encoding:'base64',size:Buffer.byteLength(text),content:Buffer.from(text).toString('base64')};}throw Error('Unscripted GitHub path: '+path);}};
}
